window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["clay"]={html:"<div class=\"own-clay\">\n  <header class=\"nav\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Northwind home\">\n      <span class=\"brand-mark\" aria-hidden=\"true\"></span>Northwind\n    </a>\n    <nav class=\"nav-links\" aria-label=\"Primary\">\n      <a href=\"#product\">Product</a>\n      <a href=\"#solutions\">Solutions</a>\n      <a href=\"#resources\">Resources</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#customers\">Customers</a>\n    </nav>\n    <div class=\"nav-right\">\n      <a class=\"nav-signin\" href=\"#\">Sign in</a>\n      <a class=\"btn btn-primary\" href=\"#\">Try free</a>\n    </div>\n  </header>\n\n  <section class=\"hero\" id=\"top\" aria-labelledby=\"heroH\">\n    <div class=\"wrap hero-grid\">\n      <div class=\"hero-copy\">\n        <p class=\"badge-pill\">New · Claymation-grade dashboards</p>\n        <h1 id=\"heroH\">Go to market with operations data that sings</h1>\n        <p class=\"lead\">Northwind gathers every region, agent run and throughput signal into one warm, playful command surface your team actually enjoys opening.</p>\n        <div class=\"hero-actions\">\n          <a class=\"btn btn-primary\" href=\"#\">Start free</a>\n          <a class=\"btn btn-secondary\" href=\"#product\">Book a demo</a>\n        </div>\n      </div>\n      <div class=\"hero-art\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 460 340\" class=\"art-svg\">\n          <rect x=\"14\" y=\"14\" width=\"432\" height=\"312\" rx=\"24\" fill=\"#faf5e8\"/>\n          <path d=\"M40 240 L150 130 L250 210 L330 120 L420 220 L420 300 L40 300 Z\" fill=\"#1a3a3a\"/>\n          <path d=\"M40 260 L140 190 L230 250 L320 175 L420 250 L420 300 L40 300 Z\" fill=\"#b8a4ed\" opacity=\".85\"/>\n          <circle cx=\"360\" cy=\"70\" r=\"30\" fill=\"#e8b94a\"/>\n          <circle cx=\"130\" cy=\"80\" r=\"20\" fill=\"#ffb084\"/>\n          <circle cx=\"210\" cy=\"60\" r=\"14\" fill=\"#a4d4c5\"/>\n        </svg>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"bento\" id=\"product\" aria-labelledby=\"bentoH\">\n    <div class=\"wrap\">\n      <div class=\"head-block\">\n        <p class=\"caption-upper\">Everything in one place</p>\n        <h2 id=\"bentoH\" class=\"display-lg\">A colorful stack of operations superpowers</h2>\n      </div>\n      <div class=\"bento-grid\">\n        <article class=\"fcard fcard-pink\">\n          <h3>Sequencer</h3>\n          <p>Turn raw regional events into ordered, repeatable operations plays.</p>\n          <div class=\"frag frag-dark\"><span></span><span></span><span></span></div>\n        </article>\n        <article class=\"fcard fcard-teal\">\n          <h3>Agent runs</h3>\n          <p>Watch every automation step and its live throughput in one feed.</p>\n          <div class=\"frag frag-light\"><b>2.8M</b><i>events/min</i></div>\n        </article>\n        <article class=\"fcard fcard-lavender\">\n          <h3>Enrichment</h3>\n          <p>Blend first-party metrics with external signals to catch drift early.</p>\n          <div class=\"frag frag-ink\"><span></span><span></span><span></span></div>\n        </article>\n        <article class=\"fcard fcard-peach\">\n          <h3>CRM sync</h3>\n          <p>Push the numbers back where the team already works.</p>\n          <div class=\"frag frag-ink\"><b>41</b><i>regions</i></div>\n        </article>\n        <article class=\"fcard fcard-ochre\">\n          <h3>Community</h3>\n          <p>Share plays and templates with every operations team on the grid.</p>\n          <div class=\"frag frag-dark\"><b>779+</b><i>playbooks</i></div>\n        </article>\n        <article class=\"fcard fcard-cream\">\n          <h3>Dashboards</h3>\n          <p>The calm, readable home for the metrics that matter most.</p>\n          <div class=\"frag frag-ink\"><span></span><span></span><span></span></div>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"product\" id=\"resources\" aria-labelledby=\"prodH\">\n    <div class=\"wrap product-grid\">\n      <div class=\"mock-card\" aria-hidden=\"true\">\n        <div class=\"mock-head\"><span>Northwind · enrichment</span><span class=\"mock-live\">live</span></div>\n        <div class=\"mock-table\">\n          <div class=\"trow thead\"><span>Region</span><span>Events</span><span>Δ</span></div>\n          <div class=\"trow\"><span>APAC</span><span>2.8M</span><span class=\"up\">+6.2%</span></div>\n          <div class=\"trow\"><span>EMEA</span><span>1.9M</span><span class=\"up\">+2.1%</span></div>\n          <div class=\"trow\"><span>AMER</span><span>1.4M</span><span class=\"down\">-1.4%</span></div>\n          <div class=\"trow\"><span>LATAM</span><span>0.8M</span><span class=\"up\">+3.9%</span></div>\n        </div>\n      </div>\n      <div class=\"product-copy\">\n        <p class=\"caption-upper\">Product UI, shown not told</p>\n        <h2 id=\"prodH\" class=\"display-lg\">Real tables, agents and flows — never a flat illustration</h2>\n        <p class=\"lead\">Northwind embeds the actual workspace inside the marketing flow: agent logs, sequencer diagrams, enrichment outputs.</p>\n        <ul class=\"check-list\">\n          <li>Realtime region federation</li>\n          <li>Agent runs with full step history</li>\n          <li>Alerts routed before throughput dips</li>\n        </ul>\n        <a class=\"btn btn-secondary\" href=\"#\">Explore the workspace</a>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"customers\" id=\"customers\" aria-labelledby=\"custH\">\n    <div class=\"wrap\">\n      <h2 id=\"custH\" class=\"display-lg center\">Teams shipping warmer operations</h2>\n      <div class=\"quote-grid\">\n        <article class=\"quote-card\">\n          <div class=\"quote-top\"><span class=\"avatar av-1\">JL</span><div><b>Jo Lang</b><span class=\"muted\">Ops Lead, fictive</span></div></div>\n          <p>“Our reviews went from a spreadsheet slog to something the team looks forward to.”</p>\n        </article>\n        <article class=\"quote-card\">\n          <div class=\"quote-top\"><span class=\"avatar av-2\">RM</span><div><b>Rhea M.</b><span class=\"muted\">Director, fictive</span></div></div>\n          <p>“The colored dashboards make the signal obvious at a glance. No more hunting.”</p>\n        </article>\n        <article class=\"quote-card\">\n          <div class=\"quote-top\"><span class=\"avatar av-3\">PT</span><div><b>Paolo T.</b><span class=\"muted\">Analyst, fictive</span></div></div>\n          <p>“Agents that actually explain their steps. Trust in the numbers is back.”</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"pricing\" id=\"pricing\" aria-labelledby=\"priceH\">\n    <div class=\"wrap\">\n      <h2 id=\"priceH\" class=\"display-lg center\">Plans for every operations crew</h2>\n      <div class=\"pricing-grid\">\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Starter</h3>\n          <p class=\"tier-price\">$0</p>\n          <p class=\"muted\">One region, one team, all the warmth.</p>\n          <ul class=\"check-list\"><li>1 region</li><li>7-day retention</li><li>Community support</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"tier tier-featured\">\n          <span class=\"badge-pill dark\">Featured</span>\n          <h3 class=\"tier-name\">Grid</h3>\n          <p class=\"tier-price\">$49</p>\n          <p class=\"tier-body\">Multi-region operations with agent runs.</p>\n          <ul class=\"check-list\"><li>18 regions</li><li>13-month retention</li><li>Alert routing</li></ul>\n          <a class=\"btn btn-on-dark\" href=\"#\">Start free</a>\n        </article>\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Enterprise</h3>\n          <p class=\"tier-price\">Custom</p>\n          <p class=\"muted\">Regulated fleets and single-tenant grids.</p>\n          <ul class=\"check-list\"><li>Unlimited regions</li><li>SSO &amp; audit</li><li>Dedicated crew</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Contact sales</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"cta-band\">\n    <div class=\"wrap cta-inner\">\n      <h2 class=\"display-md\">Turn your operations ideas into reality today</h2>\n      <p class=\"muted\">Start free — no card, no setup call, no spreadsheets.</p>\n      <a class=\"btn btn-primary btn-lg\" href=\"#\">Try free</a>\n    </div>\n  </section>\n\n  <footer class=\"foot\">\n    <div class=\"wrap foot-grid\">\n      <div class=\"foot-brand\">\n        <p class=\"foot-word\">Northwind</p>\n        <p class=\"foot-tag\">Warm operations analytics.</p>\n      </div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Product</p><a href=\"#\">Dashboards</a><a href=\"#\">Agents</a><a href=\"#\">Enrichment</a><a href=\"#\">Pricing</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Solutions</p><a href=\"#\">Operations</a><a href=\"#\">Data teams</a><a href=\"#\">Enterprise</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Resources</p><a href=\"#\">Docs</a><a href=\"#\">Community</a><a href=\"#\">Status</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Company</p><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"foot-mountain\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 1200 120\" preserveAspectRatio=\"none\"><path d=\"M0 120 L180 40 L340 96 L520 20 L700 88 L880 34 L1050 92 L1200 50 L1200 120 Z\" fill=\"#e8e0d2\"/></svg>\n    </div>\n    <div class=\"wrap foot-bottom\">\n      <p>Northwind is a fictional product. Sample data — showcase only.</p>\n      <span>© 2026 Northwind</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Clay design language ══════════════════\n   Scoped under .own-clay. Tokens from design-md/clay/DESIGN.md. Cream-tinted\n   canvas, dark-navy primary CTAs, Plain Black display (substituted by Inter\n   500 with negative tracking), the 6-color saturated feature-card palette,\n   and the deliberately cream (never dark) footer with its horizon mountain. */\n\n.own-clay {\n  --canvas: #fffaf0;\n  --surface-soft: #faf5e8;\n  --surface-card: #f5f0e0;\n  --surface-strong: #ebe6d6;\n  --ink: #0a0a0a;\n  --body: #3a3a3a;\n  --body-strong: #1a1a1a;\n  --muted: #6a6a6a;\n  --muted-soft: #9a9a9a;\n  --hairline: #e5e5e5;\n  --on-primary: #ffffff;\n  --on-dark: #ffffff;\n  --brand-pink: #ff4d8b;\n  --brand-teal: #1a3a3a;\n  --brand-lavender: #b8a4ed;\n  --brand-peach: #ffb084;\n  --brand-ochre: #e8b94a;\n  --brand-mint: #a4d4c5;\n\n  --display: \"Plain Black\", \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --body-font: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n\n  --gut: clamp(20px, 4.4cqi, 32px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--body-font);\n  font-size: 16px;\n  font-weight: 400;\n  line-height: 1.55;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n}\n.own-clay *,\n.own-clay *::before,\n.own-clay *::after { box-sizing: border-box; }\n.own-clay :focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }\n.own-clay a { color: inherit; text-decoration: none; }\n.own-clay .wrap { max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n.own-clay .center { text-align: center; }\n.own-clay .muted { color: var(--muted); }\n.own-clay .lead { color: var(--body); font-size: 17px; line-height: 1.55; }\n\n/* ── type ─────────────────────────────────────────────────────────────── */\n.own-clay .display-lg {\n  font-family: var(--display); font-weight: 500;\n  font-size: clamp(34px, 5cqi, 56px); line-height: 1.05; letter-spacing: -.035em; margin: 0;\n}\n.own-clay .display-md {\n  font-family: var(--display); font-weight: 500;\n  font-size: clamp(26px, 3.4cqi, 40px); line-height: 1.1; letter-spacing: -.02em; margin: 0;\n}\n.own-clay .caption-upper {\n  font-family: var(--body-font); font-weight: 600; font-size: 12px; letter-spacing: 1.5px;\n  text-transform: uppercase; color: var(--muted); margin: 0 0 14px;\n}\n.own-clay .head-block { max-width: 720px; margin-bottom: 44px; }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-clay .btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 44px; padding: 0 20px; border-radius: 12px;\n  font-family: var(--body-font); font-weight: 600; font-size: 14px;\n  border: 1px solid transparent; cursor: pointer; white-space: nowrap;\n  transition: background-color .15s ease, color .15s ease, border-color .15s ease, filter .15s ease;\n}\n.own-clay .btn-primary { background: var(--ink); color: var(--on-primary); }\n.own-clay .btn-primary:hover { background: #1f1f1f; }\n.own-clay .btn-secondary { background: var(--canvas); color: var(--ink); border-color: var(--hairline); }\n.own-clay .btn-secondary:hover { border-color: var(--surface-strong); }\n.own-clay .btn-on-dark { background: var(--canvas); color: var(--ink); }\n.own-clay .btn-lg { height: 48px; padding: 0 26px; font-size: 15px; }\n.own-clay .badge-pill {\n  display: inline-block; background: var(--surface-card); color: var(--ink);\n  font-size: 13px; font-weight: 500; padding: 4px 12px; border-radius: 9999px; margin-bottom: 20px;\n}\n.own-clay .badge-pill.dark { background: rgba(255,255,255,.16); color: var(--on-dark); }\n\n/* ── nav ──────────────────────────────────────────────────────────────── */\n.own-clay .nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 32px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(255,250,240,.9); border-bottom: 1px solid var(--hairline);\n  backdrop-filter: blur(8px);\n}\n.own-clay .brand { display: inline-flex; align-items: center; gap: 9px; font-family: var(--display); font-weight: 500; font-size: 19px; letter-spacing: -.03em; }\n.own-clay .brand-mark { width: 20px; height: 20px; border-radius: 6px; background: var(--ink); display: inline-block; box-shadow: inset -4px -4px 0 0 var(--brand-ochre); }\n.own-clay .nav-links { display: flex; align-items: center; gap: 26px; }\n.own-clay .nav-links a { font-size: 14px; font-weight: 500; color: var(--body); }\n.own-clay .nav-links a:hover { color: var(--ink); }\n.own-clay .nav-right { margin-left: auto; display: flex; align-items: center; gap: 16px; }\n.own-clay .nav-signin { font-size: 14px; font-weight: 500; }\n\n/* ── hero ─────────────────────────────────────────────────────────────── */\n.own-clay .hero { padding: var(--section) 0; }\n.own-clay .hero-grid { display: grid; grid-template-columns: 7fr 5fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-clay .hero h1 {\n  font-family: var(--display); font-weight: 500;\n  font-size: clamp(38px, 5.8cqi, 72px); line-height: 1; letter-spacing: -.04em; margin: 0 0 22px;\n}\n.own-clay .hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 30px; }\n.own-clay .hero-art { background: var(--surface-soft); border-radius: 24px; overflow: hidden; }\n.own-clay .art-svg { display: block; width: 100%; height: auto; }\n\n/* ── bento feature cards ─────────────────────────────────────────────── */\n.own-clay .bento { padding: var(--section) 0; background: var(--canvas); }\n.own-clay .bento-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }\n.own-clay .fcard { border-radius: 24px; padding: 32px; display: flex; flex-direction: column; }\n.own-clay .fcard h3 { font-family: var(--body-font); font-weight: 600; font-size: 18px; margin: 0 0 10px; }\n.own-clay .fcard p { margin: 0 0 20px; font-size: 15px; }\n.own-clay .fcard-pink { background: var(--brand-pink); color: var(--on-dark); }\n.own-clay .fcard-pink p { color: rgba(255,255,255,.9); }\n.own-clay .fcard-teal { background: var(--brand-teal); color: var(--on-dark); }\n.own-clay .fcard-teal p { color: rgba(255,255,255,.86); }\n.own-clay .fcard-lavender { background: var(--brand-lavender); color: var(--ink); }\n.own-clay .fcard-peach { background: var(--brand-peach); color: var(--ink); }\n.own-clay .fcard-ochre { background: var(--brand-ochre); color: var(--ink); }\n.own-clay .fcard-cream { background: var(--surface-card); color: var(--ink); }\n.own-clay .frag { margin-top: auto; border-radius: 12px; padding: 16px; display: flex; align-items: center; gap: 8px; font-family: var(--body-font); }\n.own-clay .frag-dark { background: rgba(0,0,0,.85); }\n.own-clay .frag-light { background: rgba(255,255,255,.92); color: var(--ink); gap: 10px; }\n.own-clay .frag-ink { background: rgba(0,0,0,.14); }\n.own-clay .frag span { flex: 1; height: 8px; border-radius: 4px; background: rgba(255,255,255,.35); }\n.own-clay .frag-ink span { background: var(--ink); opacity: .5; }\n.own-clay .frag b { font-family: var(--display); font-weight: 500; font-size: 24px; letter-spacing: -.03em; }\n.own-clay .frag i { font-style: normal; font-size: 12px; color: var(--muted); }\n\n/* ── product ─────────────────────────────────────────────────────────── */\n.own-clay .product { padding: var(--section) 0; background: var(--surface-soft); }\n.own-clay .product-grid { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-clay .product-copy .display-lg { max-width: 14ch; margin-bottom: 18px; }\n.own-clay .check-list { list-style: none; margin: 22px 0; padding: 0; display: grid; gap: 12px; }\n.own-clay .check-list li { position: relative; padding-left: 28px; color: var(--body); }\n.own-clay .check-list li::before { content: \"\"; position: absolute; left: 0; top: 5px; width: 16px; height: 9px; border-left: 2px solid var(--ink); border-bottom: 2px solid var(--ink); transform: rotate(-45deg); }\n.own-clay .mock-card { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 16px; padding: 24px; }\n.own-clay .mock-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; font-size: 13px; font-weight: 600; }\n.own-clay .mock-live { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .08em; color: #1a7a4a; }\n.own-clay .mock-live::before { content: \"\"; width: 7px; height: 7px; border-radius: 9999px; background: #22c55e; }\n.own-clay .mock-table { display: grid; gap: 2px; }\n.own-clay .trow { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; padding: 11px 12px; border-radius: 10px; font-size: 14px; background: var(--surface-soft); }\n.own-clay .trow.thead { background: transparent; font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); font-weight: 600; }\n.own-clay .up { color: #1a7a4a; font-weight: 600; }\n.own-clay .down { color: #c0392b; font-weight: 600; }\n\n/* ── customers ───────────────────────────────────────────────────────── */\n.own-clay .customers { padding: var(--section) 0; }\n.own-clay .customers .display-lg { margin-bottom: 44px; }\n.own-clay .quote-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-clay .quote-card { background: var(--surface-card); border-radius: 16px; padding: 24px; }\n.own-clay .quote-top { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }\n.own-clay .quote-top > div { display: flex; flex-direction: column; }\n.own-clay .quote-top b { font-size: 14px; }\n.own-clay .quote-top .muted { font-size: 12px; }\n.own-clay .avatar { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 9999px; font-size: 13px; font-weight: 600; color: var(--ink); flex: none; }\n.own-clay .av-1 { background: var(--brand-peach); }\n.own-clay .av-2 { background: var(--brand-lavender); }\n.own-clay .av-3 { background: var(--brand-mint); }\n.own-clay .quote-card p { color: var(--body); margin: 0; }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-clay .pricing { padding: var(--section) 0; background: var(--surface-soft); }\n.own-clay .pricing .display-lg { margin-bottom: 44px; }\n.own-clay .pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-clay .tier { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 16px; padding: 32px; display: flex; flex-direction: column; }\n.own-clay .tier-featured { background: var(--brand-teal); border-color: var(--brand-teal); color: var(--on-dark); }\n.own-clay .tier-name { font-family: var(--body-font); font-weight: 600; font-size: 24px; letter-spacing: -.02em; margin: 0 0 14px; }\n.own-clay .tier-price { font-family: var(--display); font-weight: 500; font-size: 40px; letter-spacing: -.03em; margin: 0 0 10px; }\n.own-clay .tier-featured .tier-body, .own-clay .tier-featured .muted { color: rgba(255,255,255,.82); }\n.own-clay .tier .check-list { margin-bottom: 24px; }\n.own-clay .tier-featured .check-list li { color: rgba(255,255,255,.9); }\n.own-clay .tier-featured .check-list li::before { border-color: var(--on-dark); }\n.own-clay .tier .btn { margin-top: auto; }\n\n/* ── CTA band ────────────────────────────────────────────────────────── */\n.own-clay .cta-band { padding: var(--section) 0 0; }\n.own-clay .cta-inner { background: var(--surface-soft); border-radius: 24px; padding: clamp(48px, 6cqi, 80px); text-align: center; display: grid; justify-items: center; gap: 14px; }\n.own-clay .cta-inner .btn { margin-top: 8px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-clay .foot { background: var(--surface-soft); padding: clamp(48px, 6cqi, 80px) 0 0; margin-top: var(--section); }\n.own-clay .foot-grid { display: grid; grid-template-columns: 1.4fr repeat(4, 1fr); gap: 24px; padding-bottom: 48px; }\n.own-clay .foot-word { font-family: var(--display); font-weight: 500; font-size: 22px; letter-spacing: -.03em; margin: 0 0 10px; }\n.own-clay .foot-tag { font-size: 14px; color: var(--body); margin: 0; }\n.own-clay .foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-clay .foot-h { font-size: 13px; font-weight: 600; color: var(--ink); margin: 0 0 4px; }\n.own-clay .foot-col a { font-size: 14px; color: var(--muted); }\n.own-clay .foot-col a:hover { color: var(--ink); }\n.own-clay .foot-mountain { display: block; width: 100%; line-height: 0; }\n.own-clay .foot-mountain svg { display: block; width: 100%; height: 80px; }\n.own-clay .foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 18px 0 28px; font-size: 13px; color: var(--muted); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-clay .hero-grid, .own-clay .product-grid { grid-template-columns: 1fr; }\n  .own-clay .bento-grid, .own-clay .quote-grid, .own-clay .pricing-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-clay .foot-grid { grid-template-columns: 1.4fr repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-clay .nav-links, .own-clay .nav-signin { display: none; }\n  .own-clay .bento-grid, .own-clay .quote-grid, .own-clay .pricing-grid { grid-template-columns: 1fr; }\n  .own-clay .foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-clay .foot-grid { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-clay *, .own-clay *::before, .own-clay *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
